// vq4d_mma: Hadamard-64 + Rademacher 4D Antipodal Gaussian VQ Tensor-Core GEMM & fused SwiGLU for DFlash.
// Supports two unified ultra-low-bit formats with per-64 UE4M4 scales (16B GPU footer for base_shifted):
//   - kBits=9  (2.375 bpw, 4D-256 antipodal = 512 pts): 152 B per 8x64 tile
//       [0..127]   uint32_t lo[32]      : lane l=(r<<2)|t -> 4 x 8-bit LUT indices (s=0..3)
//       [128..143] uint16_t sgn[8]      : row r -> 16 sign bits (bits 4*t + s)
//       [144..151] uint8_t  sc[8]       : row r -> UE4M4 unsigned scale
//       CTA steps: 8*152 = 1216 B (64B TMA-aligned, swiglu/gemm), 4*152 = 608 B (32B aligned, n32)
//   - kBits=10 (2.625 bpw, 4D-512 antipodal = 1024 pts): 168 B per 8x64 tile
//       [0..127]   uint32_t lo[32]      : lane l=(r<<2)|t -> 4 x low 8-bit LUT indices (s=0..3)
//       [128..159] uint8_t  hi2[32]     : lane l=(r<<2)|t -> 4 x 2-bit (bit0=idx[8], bit1=sign)
//       [160..167] uint8_t  sc[8]       : row r -> UE4M4 unsigned scale
//       CTA steps: 8*168 = 1344 B (64B TMA-aligned, swiglu/gemm), 4*168 = 672 B (32B aligned, n32)
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdlib>
#include <cstring>
#include <stdint.h>

namespace {

constexpr int kVqWarps = 4;
constexpr int kVqThreads = kVqWarps * 32;            // 128
constexpr int kVqNTilesPerCTA = 8;                   // 64 rows/CTA (gemm, swiglu)
constexpr int kVqRowsPerCTA = 64;
constexpr int kVqStages = 4;
constexpr int kVqN32Stages = 5;
constexpr int kVqSwgStages = 5;
constexpr int kVqDefaultSwgIlv = 192;
constexpr int kVqFooterBytes = 16;
constexpr int kVqFooterBytes12 = 48;
constexpr uint32_t kVqMagic9 = 0x56513439u;          // "VQ49"
constexpr uint32_t kVqMagic10 = 0x56513430u;         // "VQ40"
constexpr uint32_t kVqMagic11 = 0x56513442u;         // "VQ4B"
constexpr uint32_t kVqMagic12 = 0x56513443u;         // "VQ4C"

template <int kBits>
__host__ __device__ constexpr int vq4d_tile_bytes() {
  return (kBits == 9) ? 152 : ((kBits == 10) ? 168 : ((kBits == 11) ? 184 : 200));
}

template <int kBits>
__host__ __device__ constexpr int vq4d_step_bytes() {
  return kVqNTilesPerCTA * vq4d_tile_bytes<kBits>();  // 1216 B, 1344 B, or 1472 B (exact 64B multiples)
}

template <int kBits>
__host__ __device__ constexpr int vq4d_n32_step_bytes() {
  return 4 * vq4d_tile_bytes<kBits>();                // 608 B, 672 B, or 736 B (exact 32B multiples)
}

template <int kBits>
__host__ __device__ constexpr int vq4d_lut_size() {
  return (kBits == 9) ? 256 : ((kBits == 10) ? 512 : ((kBits == 11) ? 1024 : 2048));
}

